import SwiftUI

// MARK: - Brand Colors
// Note: droobPrimary, droobSecondary, droobAccent, droobBackground, droobSurface, droobOnPrimary
// are auto-generated by Xcode from the asset catalog (GeneratedAssetSymbols.swift).
// Only define additional semantic helpers and fallbacks here.

extension Color {
    static let droobError = Color.red

    // Semantic colors used throughout
    static var droobDarkBrown: Color { Color(red: 0.376, green: 0.322, blue: 0.204) }
    static var droobGold: Color { Color(red: 0.776, green: 0.663, blue: 0.420) }
    static var droobLightGold: Color { Color(red: 0.851, green: 0.737, blue: 0.533) }
    static var droobTextSecondary: Color { Color(red: 0.478, green: 0.380, blue: 0.271) }
}

// Fallback colors used in previews and when asset catalog is not available
extension Color {
    static var droobPrimaryFallback: Color { Color(red: 0.776, green: 0.663, blue: 0.420) }
    static var droobSecondaryFallback: Color { Color(red: 0.851, green: 0.737, blue: 0.533) }
    static var droobAccentFallback: Color { Color(red: 0.376, green: 0.322, blue: 0.204) }
}

// MARK: - Gradient

extension LinearGradient {
    static var droobBrand: LinearGradient {
        LinearGradient(
            colors: [
                Color(red: 0.776, green: 0.663, blue: 0.420),
                Color(red: 0.376, green: 0.322, blue: 0.204)
            ],
            startPoint: .topLeading,
            endPoint: .bottomTrailing
        )
    }
}
